---

### 📡 UDP Broadcast for ESP32 Server Discovery

UDP broadcast is a common technique used to discover devices (like an ESP32) on a local network without knowing their IP address in advance.

---

### 🔧 How It Works

1. **Client** sends a UDP broadcast packet to `255.255.255.255` (or subnet broadcast like `192.168.1.255`) on a specific port
2. **ESP32 Server** listens on that port, receives the broadcast, and replies with its IP address
3. **Client** receives the reply and now knows the ESP32's IP

---

### 💻 ESP32 Arduino Code Example

```cpp
#include <WiFi.h>
#include <WiFiUdp.h>

const char* ssid = "YOUR_SSID";
const char* password = "YOUR_PASSWORD";

WiFiUDP udp;
const int discoveryPort = 4210;
char packetBuffer[255];

void setup() {
    Serial.begin(115200);
    WiFi.begin(ssid, password);

    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }

    Serial.println("\nConnected! IP: " + WiFi.localIP().toString());

    // Start listening for UDP broadcasts
    udp.begin(discoveryPort);
    Serial.println("UDP listening on port " + String(discoveryPort));
}

void loop() {
    int packetSize = udp.parsePacket();

    if (packetSize) {
        int len = udp.read(packetBuffer, 255);
        if (len > 0) packetBuffer[len] = '\0';

        Serial.printf("Received: %s from %s\n",
            packetBuffer,
            udp.remoteIP().toString().c_str());

        // Check if it's a discovery request
        if (String(packetBuffer) == "DISCOVER") {
            // Reply with our IP address
            udp.beginPacket(udp.remoteIP(), udp.remotePort());
            String response = "ESP32_HERE:" + WiFi.localIP().toString();
            udp.print(response);
            udp.endPacket();

            Serial.println("Sent discovery response: " + response);
        }
    }
}
```

---

### 💻 Client Code (Python Example)

```python
import socket
import time

DISCOVERY_PORT = 4210
BROADCAST_IP = "255.255.255.255"
MESSAGE = "DISCOVER"

def discover_esp32():
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
    sock.settimeout(5)

    print(f"Broadcasting discovery on port {DISCOVERY_PORT}...")
    sock.sendto(MESSAGE.encode(), (BROADCAST_IP, DISCOVERY_PORT))

    try:
        data, addr = sock.recvfrom(1024)
        response = data.decode()
        print(f"Found device at {addr[0]}: {response}")
        return addr[0]
    except socket.timeout:
        print("No device found!")
        return None
    finally:
        sock.close()

esp32_ip = discover_esp32()
```

