## Search Results: ESP32 Arduino mDNS Query - Resolve Windows PC Hostname

Based on the search query **"ESP32 Arduino mDNS query resolve Windows PC hostname code example"**, here are the key findings:

---

### 📌 Overview

mDNS (Multicast DNS) allows devices on a local network to resolve hostnames without a DNS server. Windows PCs broadcast their hostname as `<computername>.local` via mDNS (using the **Bonjour** protocol or Windows 10+ built-in mDNS).

---

### 💻 Code Example: ESP32 Resolving a Windows PC Hostname via mDNS

```cpp
#include <WiFi.h>
#include <ESPmDNS.h>

const char* ssid     = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

// Your Windows PC hostname (without .local)
// Find it via: Settings > System > About > Device Name
const char* targetHostname = "DESKTOP-ABC123"; // replace with your PC name

void setup() {
  Serial.begin(115200);
  delay(1000);

  // Connect to WiFi
  Serial.print("Connecting to WiFi...");
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi connected! IP: " + WiFi.localIP().toString());

  // Initialize mDNS
  if (!MDNS.begin("esp32-device")) {
    Serial.println("Error starting mDNS!");
    return;
  }
  Serial.println("mDNS responder started");

  // Query mDNS to resolve the Windows PC hostname
  Serial.printf("Resolving hostname: %s.local\n", targetHostname);

  // Method 1: Using queryHost() - synchronous resolution
  IPAddress resolvedIP = MDNS.queryHost(targetHostname);

  if (resolvedIP.toString() == "0.0.0.0") {
    Serial.println("Host not found!");
  } else {
    Serial.printf("Resolved %s.local -> %s\n", 
                  targetHostname, resolvedIP.toString().c_str());
  }
}

void loop() {
  // Nothing needed here for basic resolution
}
```

---

### 💻 Extended Example: mDNS Query with Retry Logic

```cpp
#include <WiFi.h>
#include <ESPmDNS.h>

const char* ssid        = "YOUR_WIFI_SSID";
const char* password    = "YOUR_WIFI_PASSWORD";
const char* pcHostname  = "YOUR-PC-NAME"; // Windows hostname without .local

IPAddress serverIP;
bool hostResolved = false;

bool resolveHostname(const char* hostname, int retries = 5) {
  for (int i = 0; i < retries; i++) {
    Serial.printf("Attempt %d: Resolving %s.local ...\n", i + 1, hostname);

    IPAddress ip = MDNS.queryHost(hostname, 3000); // 3 second timeout

    if (ip.toString() != "0.0.0.0") {
      Serial.printf("✅ Resolved: %s.local = %s\n", hostname, ip.toString().c_str());
      serverIP = ip;
      return true;
    }

    Serial.println("❌ Not resolved, retrying...");
    delay(2000);
  }
  return false;
}

void setup() {
  Serial.begin(115200);
  delay(1000);

  // Connect to WiFi
  WiFi.begin(ssid, password);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\n✅ WiFi Connected: " + WiFi.localIP().toString());

  // Start mDNS
  if (!MDNS.begin("esp32")) {
    Serial.println("Failed to start mDNS");
    return;
  }

  // Resolve Windows PC hostname
  hostResolved = resolveHostname(pcHostname);

  if (!hostResolved) {
    Serial.println("⚠️ Could not resolve PC hostname. Will retry in loop.");
  }
}

void loop() {
  if (!hostResolved) {
    hostResolved = resolveHostname(pcHostname, 1);
    if (!hostResolved) {
      delay(5000); // Wait 5 seconds before next attempt
    }
  } else {
    // Use serverIP here for HTTP requests, TCP connections, etc.
    Serial.printf("Server IP: %s\n", serverIP.toString().c_str());
    delay(10000);
  }
}
```

---

### 💻 Advanced Example: mDNS Service Discovery (Find PC by Service)

```cpp
#include <WiFi.h>
