Based on my research, here are concrete answers to your mDNS questions for ESP32 Arduino + Windows 11:

## 1. Windows PC mDNS Advertising

**Yes, Windows 11 can advertise itself as `hostname.local`**, but with caveats:

- **Built-in support**: Windows 10/11 includes native mDNS via the DNS Client service. Your PC automatically responds to `<computername>.local` queries on the local network.
- **Requirements**:
  - Network profile must be set to **Private** (not Public)
  - Firewall must allow **UDP port 5353** (often blocked by default)
  - Registry key: `HKLM\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters\EnableMDNS = 1`

**To enable firewall access** (PowerShell as admin):
```powershell
New-NetFirewallRule -DisplayName "mDNS (UDP-In)" -Direction Inbound -Protocol UDP -LocalPort 5353 -Action Allow -Profile Any
New-NetFirewallRule -DisplayName "mDNS (UDP-Out)" -Direction Outbound -Protocol UDP -RemotePort 5353 -Action Allow -Profile Any
```

**Alternative**: Install **Apple Bonjour for Windows** (Bonjour Print Services) for more reliable mDNS support, especially if the native implementation is unreliable.

---

## 2. ESP32 mDNS Resolution Support

**Yes, ESPmDNS library supports resolving `.local` hostnames**, but reliability varies:

- **Library**: `ESPmDNS.h` (built into ESP32 Arduino Core)
- **Function**: `MDNS.queryHost("hostname")` returns `IPAddress`
- **Windows PC resolution**: Works in theory, but has known issues:
  - Returns `IPAddress(0,0,0,0)` on failure (no exception)
  - Intermittent failures reported in practice
  - Timeout issues on congested networks
  - Router/network topology dependent

---

## 3. ESP32 Arduino Code for .local Resolution

```cpp
#include <WiFi.h>
#include <ESPmDNS.h>
#include <HTTPClient.h>

const char* ssid = "YOUR_SSID";
const char* password = "YOUR_PASSWORD";
const char* serverHostname = "faust-station"; // without .local

IPAddress serverIP;

bool resolveServer() {
    Serial.printf("Resolving %s.local...\n", serverHostname);

    // Query with 5 second timeout
    IPAddress ip = MDNS.queryHost(serverHostname, 5000);

    if (ip == IPAddress(0, 0, 0, 0)) {
        Serial.println("Resolution failed!");
        return false;
    }

    serverIP = ip;
    Serial.printf("Resolved to: %s\n", ip.toString().c_str());
    return true;
}

void setup() {
    Serial.begin(115200);

    // Connect to WiFi
    WiFi.begin(ssid, password);
    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }
    Serial.println("\nConnected!");

    // Wait for network to stabilize
    delay(2000);

    // Initialize mDNS (required even for queries)
    if (!MDNS.begin("esp32-client")) {
        Serial.println("mDNS init failed!");
        return;
    }

    // Resolve the server with retry logic
    int retries = 3;
    while (retries-- > 0 && !resolveServer()) {
        Serial.println("Retrying...");
        delay(2000);
    }

    if (serverIP != IPAddress(0, 0, 0, 0)) {
        // Make HTTP request using resolved IP
        HTTPClient http;
        String url = "http://" + serverIP.toString() + ":8080/api/endpoint";
        http.begin(url);
        int httpCode = http.GET();
        if (httpCode > 0) {
            Serial.println(http.getString());
        }
        http.end();
    }
}

void loop() {
    // Periodically re-resolve if connection lost
    delay(60000);
}
