#include <WiFi.h>
#include <WiFiUdp.h>

WiFiUDP udp;
const int BROADCAST_PORT = 4210;
char packetBuffer[255];
IPAddress serverIP;
int serverPort = 0;

void setup() {
    Serial.begin(115200);
    WiFi.begin(ssid, password);
    while (WiFi.status() != WL_CONNECTED) delay(500);

    udp.begin(BROADCAST_PORT);
    Serial.println("Listening for server broadcasts...");
}

void loop() {
    int packetSize = udp.parsePacket();
    if (packetSize) {
        int len = udp.read(packetBuffer, 255);
        if (len > 0) packetBuffer[len] = '\0';

        // Parse "FAUST-SERVER:192.168.1.100:8080"
        if (strncmp(packetBuffer, "FAUST-SERVER:", 13) == 0) {
            char* ipStr = strtok(packetBuffer + 13, ":");
            char* portStr = strtok(NULL, ":");

            serverIP.fromString(ipStr);
            serverPort = atoi(portStr);

            Serial.printf("Found server: %s:%d\n", ipStr, serverPort);
        }
    }
}
